import json
import csv

schedule = [
    {"job": 0, "op": 0, "machine": 1, "start": 0, "end": 5, "dur": 5},  # Frozen
    {"job": 1, "op": 0, "machine": 0, "start": 0, "end": 5, "dur": 5},  # Frozen
    {"job": 0, "op": 1, "machine": 2, "start": 5, "end": 11, "dur": 6},  
    {"job": 3, "op": 0, "machine": 0, "start": 5, "end": 12, "dur": 7},  
    {"job": 0, "op": 2, "machine": 0, "start": 17, "end": 22, "dur": 5},  

    {"job": 2, "op": 0, "machine": 1, "start": 20, "end": 24, "dur": 4},
    {"job": 2, "op": 1, "machine": 0, "start": 24, "end": 32, "dur": 8},  # Fixed precedence
    {"job": 2, "op": 2, "machine": 2, "start": 32, "end": 37, "dur": 5},  

    {"job": 3, "op": 1, "machine": 1, "start": 24, "end": 29, "dur": 5},

    {"job": 1, "op": 1, "machine": 2, "start": 25, "end": 30, "dur": 5},  # MC1
    {"job": 1, "op": 2, "machine": 0, "start": 32, "end": 39, "dur": 7},  # After J2-Op1

    {"job": 3, "op": 2, "machine": 0, "start": 39, "end": 43, "dur": 4},  # MC2
]

# Validate
baseline = json.load(open('/app/data/baseline_solution.json'))
baseline_map = {(op['job'], op['op']): op for op in baseline['schedule']}

makespan = max(op['end'] for op in schedule)
total_start_shift = sum(abs(op['start'] - baseline_map[(op['job'], op['op'])]['start']) for op in schedule)
machine_changes = sum(1 for op in schedule if op['machine'] != baseline_map[(op['job'], op['op'])]['machine'])

downtimes = [{'machine': 1, 'start': 5, 'end': 20}, {'machine': 2, 'start': 12, 'end': 25}]

violations = []
for op in schedule:
    for dt in downtimes:
        if dt['machine'] == op['machine']:
            if not (op['end'] <= dt['start'] or op['start'] >= dt['end']):
                violations.append(f"Downtime: Job {op['job']} Op {op['op']}")

for job_id in range(4):
    ops = sorted([op for op in schedule if op['job'] == job_id], key=lambda x: x['op'])
    for i in range(len(ops) - 1):
        if ops[i]['end'] > ops[i+1]['start']:
            violations.append(f"Precedence: Job {job_id} Op {ops[i]['op']}->{ops[i+1]['op']}")

print(f"Makespan: {makespan} (limit: 39.6)")
print(f"Start shift: {total_start_shift} (limit: 120)")
print(f"Machine changes: {machine_changes} (limit: 4)")
print(f"Violations: {len(violations)}")
if violations:
    for v in violations:
        print(f"  - {v}")

for job_id in range(4):
    ops = sorted([op for op in schedule if op['job'] == job_id], key=lambda x: x['op'])
    print(f"Job {job_id} finishes at {ops[-1]['end']}")

# Check machine conflicts
machine_ops = {}
for op in schedule:
    if op['machine'] not in machine_ops:
        machine_ops[op['machine']] = []
    machine_ops[op['machine']].append(op)

for machine, ops in machine_ops.items():
    sorted_ops = sorted(ops, key=lambda x: x['start'])
    for i in range(len(sorted_ops) - 1):
        if sorted_ops[i]['end'] > sorted_ops[i+1]['start']:
            print(f"Machine conflict on M{machine}: J{sorted_ops[i]['job']}-Op{sorted_ops[i]['op']} overlaps with J{sorted_ops[i+1]['job']}-Op{sorted_ops[i+1]['op']}")

if len(violations) == 0:
    if makespan <= 39.6 and total_start_shift <= 120 and machine_changes <= 4:
        print("\n✓✓✓ FEASIBLE SOLUTION! ✓✓✓")
        result = {
            "status": "FEASIBLE",
            "makespan": makespan,
            "schedule": sorted(schedule, key=lambda x: (x['start'], x['job'], x['op']))
        }
    else:
        print(f"\nINFEASIBLE (constraints not met)")
        result = {
            "status": "INFEASIBLE",
            "makespan": makespan,
            "schedule": sorted(schedule, key=lambda x: (x['start'], x['job'], x['op']))
        }

    with open('/app/output/solution.json', 'w') as f:
        json.dump(result, f, indent=2)

    with open('/app/output/schedule.csv', 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['job', 'op', 'machine', 'start', 'end', 'dur'])
        writer.writeheader()
        writer.writerows(result['schedule'])

    print("Solution written to /app/output/!")

